      grid-template-columns: minmax(0, 1.65fr) minmax(320px, 1fr);
      gap: 18px;
      margin-top: 30px;
    }
    .preview {
      position: relative;
      display: grid;
      grid-template-rows: auto 1fr;
      min-width: 0;
      min-height: 464px;
      overflow: hidden;
      border: 1px solid #cdd3c3;
      border-radius: 16px;
      background-color: #e5e9de;
      background-image: radial-gradient(#b8c2ae 1px, transparent 1px);
      background-size: 17px 17px;
      background-position: center;
    }
    .preview-header { position: relative; z-index: 1; padding: 17px 18px 0; }
    .preview-label {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      padding: 7px 10px;
      border: 1px solid #d1d7ca;
      border-radius: 6px;
      background: #f5f6f0;
      font: 600 10px/1 var(--mono);
      letter-spacing: .07em;
      text-transform: uppercase;
