      border-radius: 20px;
    }
    .plan-label { color: #52653c; font: 700 10px/1.3 var(--mono); letter-spacing: .12em; text-transform: uppercase; }
    .pricing-card h2 { margin-top: 6px; font-size: 25px; letter-spacing: -.055em; line-height: 1.15; }
    .plan-description { margin-top: 6px; font-size: 13px; color: var(--muted); line-height: 1.4; }
    .price { margin-top: 18px; font-size: 39px; font-weight: 780; line-height: 1; letter-spacing: -.07em; }
    .price span { margin-left: 5px; font-size: 12px; font-weight: 500; color: var(--muted); letter-spacing: 0; }
    .plan-cta {
      display: block;
      margin-top: 17px;
      padding: 10px;
      border-radius: 7px;
      color: #263216;
      background: var(--accent);
      text-align: center;
      font-size: 13px;
      font-weight: 750;
    }
    .features { display: grid; gap: 8px; margin: 16px 0 0; padding: 14px 0 0; border-top: 1px solid #e9ece4; list-style: none; }
    .features li { display: flex; align-items: center; gap: 9px; font-size: 12px; }
    .features li::before { content: "✓"; color: #4c7034; font-size: 13px; font-weight: 800; }
    .settings {
      display: flex;
      flex-direction: column;
      padding: 22px;
      border: 1px solid var(--line);
      border-radius: 16px;
      background: #fff;
    }
    .section-header { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
    .section-header h2 { font-size: 17px; font-weight: 750; letter-spacing: -.035em; }
    .reset {
      padding: 6px 9px;
      border: 1px solid var(--line);
      border-radius: 6px;
      color: #495244;
      background: #fff;
      font-size: 12px;
      font-weight: 600;
    }
    .reset:hover { background: #f2f4ed; }
    .sliders { display: grid; gap: 15px; margin-top: 20px; }
    .field { display: grid; gap: 6px; }
    .field-header { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
    label { font-size: 13px; font-weight: 650; }
    .value {
      min-width: 51px;
      padding: 3px 6px;
      border-radius: 5px;
      background: #eff2eb;
      color: #414d3b;
      font: 11px/1.35 var(--mono);
      text-align: center;
      white-space: nowrap;
    }
    input[type="range"] {
      --fill: 0%;
      appearance: none;
      width: 100%;
      height: 18px;
      margin: 0;
      border-radius: 10px;
      background: linear-gradient(to right, #729651 var(--fill), #e5e9e1 var(--fill)) center / 100% 4px no-repeat;
      cursor: pointer;
    }
    input[type="range"]::-webkit-slider-thumb {
      appearance: none;
      width: 15px;
      height: 15px;
      border: 2px solid #fff;
      border-radius: 50%;
      background: #53733a;
      box-shadow: 0 0 0 1px #53733a;
    }
    input[type="range"]::-moz-range-thumb {
      width: 11px;
      height: 11px;
      border: 2px solid #fff;
      border-radius: 50%;
      background: #53733a;
      box-shadow: 0 0 0 1px #53733a;
    }
    .color-controls { margin-top: 17px; padding-top: 14px; border-top: 1px solid #edf0e9; }
    .color-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 13px; }
    .color-picker { display: flex; align-items: center; gap: 8px; }
    input[type="color"] {
      width: 31px;
      height: 27px;
      padding: 3px;
      border: 1px solid var(--line);
      border-radius: 5px;
      background: white;
      cursor: pointer;
    }
    input[type="color"]::-webkit-color-swatch-wrapper { padding: 0; }
    input[type="color"]::-webkit-color-swatch { border: 0; border-radius: 2px; }
    input[type="color"]::-moz-color-swatch { border: 0; border-radius: 2px; }
    .export {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 12px 24px;
      align-items: start;
      margin-top: 18px;
      padding: 18px 22px;
      border-radius: 14px;
      color: #f2f5ed;
      background: #232a20;
    }
    .export h2 { font-size: 15px; letter-spacing: -.02em; }
    .code { grid-column: 1; grid-row: 2; min-width: 0; overflow: auto; margin: 0; font: 12px/1.6 var(--mono); }
    .property { color: #bcccaf; }
    .css-value { color: #d9fa85; }
    .copy {
      grid-column: 2;
      grid-row: 1 / span 2;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 7px;
      min-width: 119px;
      padding: 9px 12px;
      border: 1px solid #667161;
      border-radius: 7px;
      background: #303a2d;
      color: #f2f5ed;
      font-size: 12px;
      font-weight: 650;
    }
    .copy:hover { background: #414f3c; }
    .copy:focus-visible { outline-color: var(--accent); }
    .visually-hidden {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
    }
    @media (max-width: 780px) {
      .workspace { grid-template-columns: minmax(0, 1fr) minmax(270px, 1fr); }
      .shell { width: calc(100% - 40px); }
