    @media (max-width: 600px) {
      .shell { width: calc(100% - 28px); }
      main.shell { padding-top: 30px; }
      .workspace { grid-template-columns: minmax(0, 1fr); margin-top: 22px; }
      .preview { min-height: 405px; }
      .preview-stage { padding: 18px 20px 28px; }
      .settings { padding: 18px; }
      .export { padding: 16px; gap: 12px; align-items: center; }
      .copy { grid-row: 1; }
      .code { grid-column: 1 / -1; }
    }
  </style>
</head>
<body>
  <header class="masthead">
    <div class="shell">
      <span class="mark" aria-hidden="true"><ryugi-icon name="layers" size="16"></ryugi-icon></span>
      <span class="brand">Shadow Studio</span>
    </div>
  </header>
  <main class="shell">
    <h1>Pricing card shadow</h1>
    <p class="intro">Tune the shadow and corner radius on a sample pricing card, then copy the CSS.</p>

    <div class="workspace">
      <section class="preview" aria-labelledby="preview-title">
        <div class="preview-header">
          <h2 class="preview-label" id="preview-title">Live preview</h2>
        </div>
        <div class="preview-stage">
          <article class="pricing-card" id="pricing-card">
            <p class="plan-label">Monthly plan</p>
            <h2>Pro</h2>
            <p class="plan-description">For small teams building together.</p>
            <p class="price">$24<span> / month</span></p>
            <span class="plan-cta">Choose Pro</span>
            <ul class="features">
              <li>Unlimited projects</li>
              <li>Up to 10 team members</li>
              <li>Priority support</li>
            </ul>
          </article>
        </div>
      </section>

      <form class="settings" id="shadow-settings" aria-labelledby="settings-title">
        <div class="section-header">
          <h2 id="settings-title">Shadow settings</h2>
          <button class="reset" id="reset-settings" type="reset">Reset</button>
        </div>

        <div class="sliders">
          <div class="field">
            <div class="field-header">
              <label for="elevation">Elevation</label>
              <output class="value" id="elevation-value" for="elevation">14 px</output>
            </div>
            <input id="elevation" type="range" min="-40" max="64" value="14" aria-describedby="elevation-description">
            <span class="visually-hidden" id="elevation-description">Vertical shadow offset in pixels.</span>
          </div>
          <div class="field">
            <div class="field-header">
              <label for="blur">Blur</label>
              <output class="value" id="blur-value" for="blur">32 px</output>
            </div>
            <input id="blur" type="range" min="0" max="100" value="32">
          </div>
          <div class="field">
            <div class="field-header">
              <label for="spread">Spread</label>
              <output class="value" id="spread-value" for="spread">−8 px</output>
            </div>
            <input id="spread" type="range" min="-32" max="48" value="-8">
          </div>
          <div class="field">
            <div class="field-header">
              <label for="radius">Corner radius</label>
              <output class="value" id="radius-value" for="radius">20 px</output>
            </div>
            <input id="radius" type="range" min="0" max="64" value="20">
          </div>
        </div>

        <div class="color-controls">
          <div class="color-row">
            <label for="shadow-color">Shadow colour</label>
            <div class="color-picker">
              <input id="shadow-color" type="color" value="#232f1c">
              <output class="value" id="color-value" for="shadow-color">#232F1C</output>
            </div>
          </div>
          <div class="field">
            <div class="field-header">
              <label for="opacity">Shadow opacity</label>
              <output class="value" id="opacity-value" for="opacity">28%</output>
            </div>
            <input id="opacity" type="range" min="0" max="100" value="28">
          </div>
        </div>
      </form>
    </div>

    <section class="export" aria-labelledby="css-title">
      <h2 id="css-title">Generated CSS</h2>
      <pre class="code" id="generated-css" tabindex="0"><code><span class="property">box-shadow:</span> <span class="css-value" id="shadow-css">0 14px 32px -8px rgb(35 47 28 / 28%)</span>;
<span class="property">border-radius:</span> <span class="css-value" id="radius-css">20px</span>;</code></pre>
      <button class="copy" id="copy-css" type="button">
        <ryugi-icon name="copy" size="14" aria-hidden="true"></ryugi-icon>
        <span id="copy-label">Copy CSS</span>
      </button>
      <span class="visually-hidden" id="copy-status" role="status"></span>
    </section>
  </main>

  <script>
    const settings = document.getElementById('"'shadow-settings');
    const card = document.getElementById('pricing-card');
    const color = document.getElementById('shadow-color');
    const colorValue = document.getElementById('color-value');
    const sliders = [...settings.querySelectorAll('input[type=\"range\"]')].map((input) => ({
      input,
      output: document.getElementById(input.id + '-value'),
      unit: input.id === 'opacity' ? '%' : ' px',
    }));
    const [elevation, blur, spread, radius, opacity] = sliders.map(({ input }) => input);
    const shadowCSS = document.getElementById('shadow-css');
    const radiusCSS = document.getElementById('radius-css');
    const generatedCSS = document.getElementById('generated-css');
    const copyButton = document.getElementById('copy-css');
    const copyLabel = document.getElementById('copy-label');
    const copyStatus = document.getElementById('copy-status');
    let copyAttempt = 0;

    function render() {
      for (const { input, output, unit } of sliders) {
        output.value = input.value.replace('-', '−') + unit;
        input.setAttribute('aria-valuetext', output.value);
        const fill = (input.valueAsNumber - Number(input.min)) / (Number(input.max) - Number(input.min));
        input.style.setProperty('--fill', (fill * 100) + '%');
      }

      colorValue.value = color.value.toUpperCase();
      const channels = [1, 3, 5].map((start) => parseInt(color.value.slice(start, start + 2), 16));
      const shadow = "'`0 ${elevation.value}px ${blur.value}px ${spread.value}px rgb(${channels.join('"' ')} / "'${opacity.value}%)`;
      const corners = radius.value + '"'px';
      card.style.boxShadow = shadow;
      card.style.borderRadius = corners;
      shadowCSS.textContent = shadow;
      radiusCSS.textContent = corners;
      copyAttempt += 1;
      copyLabel.textContent = 'Copy CSS';
      copyStatus.textContent = '';
    }

    function selectCSS() {
      generatedCSS.focus();
      const range = document.createRange();
      range.selectNodeContents(generatedCSS);
      const selection = window.getSelection();
      selection.removeAllRanges();
      selection.addRange(range);
    }

    copyButton.addEventListener('click', async () => {
      const attempt = ++copyAttempt;
      const css = generatedCSS.textContent;
      copyStatus.textContent = '';
      try {
        await navigator.clipboard.writeText(css);
      } catch {
        if (attempt "'!== copyAttempt) return;
        selectCSS();
        if (!document.execCommand('"'copy')) {
          copyStatus.textContent = 'CSS selected. Use your keyboard shortcut to copy.';
          copyLabel.textContent = 'CSS selected';
          return;
        }
        window.getSelection().removeAllRanges();
        copyButton.focus();
      }
      if (attempt "'!== copyAttempt) return;
      copyLabel.textContent = '"'Copied"'!'"';
      copyStatus.textContent = 'CSS copied to clipboard.';
    });

    settings.addEventListener('input', render);
    settings.addEventListener('change', render);
    settings.addEventListener('reset', () => requestAnimationFrame(render));
    render();
  </script>
</body>
</html>
EOF"

