    const copyButton = document.getElementById('copy-css');
    const copyLabel = document.getElementById('copy-label');
    const copyStatus = document.getElementById('copy-status');
    let copyAttempt = 0;

    function render() {
      for (const { input, output, unit } of sliders) {
        output.value = input.value.replace('-', '−') + unit;
        input.setAttribute('aria-valuetext', output.value);
        const fill = (input.valueAsNumber - Number(input.min)) / (Number(input.max) - Number(input.min));
        input.style.setProperty('--fill', (fill * 100) + '%');
      }

      colorValue.value = color.value.toUpperCase();
      const channels = [1, 3, 5].map((start) => parseInt(color.value.slice(start, start + 2), 16));
      const shadow = "'`0 ${elevation.value}px ${blur.value}px ${spread.value}px rgb(${channels.join('"' ')} / "'${opacity.value}%)`;
      const corners = radius.value + '"'px';
      card.style.boxShadow = shadow;
      card.style.borderRadius = corners;
      shadowCSS.textContent = shadow;
      radiusCSS.textContent = corners;
      copyAttempt += 1;
      copyLabel.textContent = 'Copy CSS';
      copyStatus.textContent = '';
    }

    function selectCSS() {
      generatedCSS.focus();
      const range = document.createRange();
      range.selectNodeContents(generatedCSS);
      const selection = window.getSelection();
      selection.removeAllRanges();
      selection.addRange(range);
    }

    copyButton.addEventListener('click', async () => {
      const attempt = ++copyAttempt;
      const css = generatedCSS.textContent;
      copyStatus.textContent = '';
      try {
        await navigator.clipboard.writeText(css);
      } catch {
        if (attempt "'!== copyAttempt) return;
        selectCSS();
        if (!document.execCommand('"'copy')) {
          copyStatus.textContent = 'CSS selected. Use your keyboard shortcut to copy.';
          copyLabel.textContent = 'CSS selected';
          return;
        }
        window.getSelection().removeAllRanges();
        copyButton.focus();
      }
      if (attempt "'!== copyAttempt) return;
      copyLabel.textContent = '"'Copied"'!'"';
      copyStatus.textContent = 'CSS copied to clipboard.';
    });

    settings.addEventListener('input', render);
    settings.addEventListener('change', render);
    settings.addEventListener('reset', () => requestAnimationFrame(render));
    render();
